from pathlib import Path

path = Path('src/booking-search.staging.server.ts')
text = path.read_text()
old = '''app.get(["/favicon.ico", "/apple-touch-icon.png", "/apple-touch-icon-precomposed.png"], (_q, res) => {\n  res.redirect(302, "https://pin-ngo.com/favicon.ico");\n});'''
b64 = ''''''
new = f'''const BOOKING_ICON_PNG = Buffer.from("{b64}", "base64");\napp.get(["/favicon.ico", "/apple-touch-icon.png", "/apple-touch-icon-precomposed.png"], (_q, res) => {{\n  res.set("Cache-Control", "public, max-age=86400, immutable");\n  res.type("png").send(BOOKING_ICON_PNG);\n}});'''
if text.count(old) != 1:
    raise SystemExit(f'Expected exactly one icon redirect block, found {text.count(old)}')
path.write_text(text.replace(old, new, 1))
